mapper.select:
select 
from comment
where status = 0
  and post_id = #{postId, jdbcType=BINARY}
  and parent_comment_id is null

  and (create_time < #{boundaryTime}
    or (create_time = #{boundaryTime} and id < #{boundaryId, jdbcType=BINARY}))

order by create_time desc, id desc
limit #{limit}

select 
from comment
where status = 0
  and root_comment_id = #{rootCommentId, jdbcType=BINARY}
  and parent_comment_id is not null

  and (create_time > #{boundaryTime}
    or (create_time = #{boundaryTime} and id > #{boundaryId, jdbcType=BINARY}))

order by create_time asc, id asc
limit #{limit}

select 
from comment
where id = #{id, jdbcType=BINARY}

select count(1)
from comment
where status = 0
  and id = #{commentId, jdbcType=BINARY}
  and post_id = #{postId, jdbcType=BINARY}
  and parent_comment_id is null

select from ( select , row_number() over (partition by post_id order by create_time desc, id desc) as rn from comment where status = 0 and post_id in
#{pid, jdbcType=BINARY}
) ranked where rn = 1 order by post_id asc
